const redis1 = JSON.parse($json.Redis1);
const redis2 = JSON.parse($json.Redis2);

const combinadoSemDuplicatas = Array.from(new Set([...redis1, ...redis2]));

const mensagem = combinadoSemDuplicatas.join(" ");

return [{ json: { mensagem_completa: mensagem } }];

// Extrair a URL do campo especificado
const documentUrl = $json.body?.data?.message?.documentMessage?.url;

// Verificar se a URL existe
if (!documentUrl) {
  return [{
    json: {
      success: false,
      error: "URL não encontrada no caminho especificado",
      path_checked: "$json.body.data.message.documentMessage.url"
    }
  }];
}

try {
  // Fazer requisição HTTP para baixar o conteúdo da URL
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: documentUrl,
    encoding: 'binary', // Para arquivos binários
    timeout: 30000, // 30 segundos de timeout
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
    }
  });

  // Determinar o tipo de conteúdo
  let contentType = 'application/octet-stream';
  let isText = false;

  // Tentar detectar o tipo baseado nos primeiros bytes
  const firstBytes = response.slice(0, 4);

  if (firstBytes[0] === 0xFF && firstBytes[1] === 0xD8) {
    contentType = 'image/jpeg';
  } else if (firstBytes[0] === 0x89 && firstBytes[1] === 0x50) {
    contentType = 'image/png';
  } else if (response.slice(0, 4).toString() === '%PDF') {
    contentType = 'application/pdf';
  } else {
    // Tentar como texto
    try {
      const textContent = response.toString('utf8');
      if (textContent && !textContent.includes('\uFFFD')) {
        isText = true;
        contentType = 'text/plain';
      }
    } catch (e) {
      // Não é texto válido
    }
  }

  // Preparar resposta
  const result = {
    json: {
      success: true,
      url: documentUrl,
      contentType: contentType,
      size: response.length,
      isText: isText,
      downloadedAt: new Date().toISOString()
    }
  };

  // Se for texto, incluir no JSON
  if (isText) {
    result.json.textContent = response.toString('utf8');
  } else {
    // Se for binário, converter para base64
    result.json.base64Content = response.toString('base64');
  }

  // Incluir dados binários para processamento posterior
  result.binary = {
    data: {
      data: response,
      mimeType: contentType,
      fileName: `downloaded_file_${Date.now()}`,
      fileExtension: getFileExtension(contentType)
    }
  };

  return [result];

} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      url: documentUrl,
      errorType: error.name || 'UnknownError'
    }
  }];
}

// Função auxiliar para determinar extensão do arquivo
function getFileExtension(mimeType) {
  const extensions = {
    'image/jpeg': 'jpg',
    'image/png': 'png',
    'image/gif': 'gif',
    'application/pdf': 'pdf',
    'text/plain': 'txt',
    'application/json': 'json',
    'text/html': 'html',
    'application/zip': 'zip'
  };

  return extensions[mimeType] || 'bin';
}

// Loop over input items
for (const item of $input.all()) {

  // Busca a informação diretamente do nó "Webhook EVO"
  const webhookData = $('Webhook EVO').first().json;
  const conversationText = webhookData?.body?.data?.message?.conversation || "";

  // ==========================================
  // 1. LÓGICA DO ID DA VAGA (Mantida)
  // ==========================================
  const matchId = conversationText.match(/ID:\s*(\d+)/i);

  if (matchId) {
    item.json.id_vaga = parseInt(matchId[1], 10);
  } else {
    item.json.id_vaga = null;
  }

  // ==========================================
  // 2. NOVA LÓGICA DA ORIGEM
  // ==========================================
  let origem = "Geral"; // Definimos "Geral" como o valor padrão inicial

  // O /palavra/i procura a palavra ignorando se o usuário digitou com maiúsculas ou minúsculas
  if (/instagram/i.test(conversationText)) {
    origem = "Instagram";
  } else if (/facebook/i.test(conversationText)) {
    origem = "Facebook";
  } else if (/linkedin/i.test(conversationText)) {
    origem = "LinkedIn";
  }

  // Salva o resultado encontrado no novo campo 'origem'
  item.json.origem = origem;
}

// Retorna os itens atualizados
return $input.all();
